-- State transitions declared for Survey: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION survey.survey_surveys_session_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."session_state" IS DISTINCT FROM OLD."session_state" AND NOT (
           (COALESCE(OLD."session_state"::text, ''), COALESCE(NEW."session_state"::text, '')) IN (('', 'ready'), ('in_progress', ''), ('ready', ''), ('ready', 'in_progress'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: survey_surveys.session_state % -> %', OLD."session_state", NEW."session_state"
            USING ERRCODE = 'check_violation', COLUMN = 'session_state', CONSTRAINT = 'tg_survey_surveys__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS survey_surveys_session_state_transition_check ON survey.survey_surveys;
CREATE TRIGGER survey_surveys_session_state_transition_check
    BEFORE UPDATE OF "session_state" ON survey.survey_surveys
    FOR EACH ROW EXECUTE FUNCTION survey.survey_surveys_session_state_transition_check();
